// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Login Log in with email and password (plus the second factor when enrolled)
	// (POST /api/admin/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End the current session
	// (POST /api/admin/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetMe The current user, organizations and marinas with roles and permissions
	// (GET /api/admin/v1/auth/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Change the name or locale of the current user
	// (PATCH /api/admin/v1/auth/me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// ChangePassword Change the password (other sessions are revoked)
	// (POST /api/admin/v1/auth/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// ConfirmPasswordReset Set a new password with a reset or invitation token (single use; every session is revoked)
	// (POST /api/admin/v1/auth/password-reset/confirm)
	ConfirmPasswordReset(w http.ResponseWriter, r *http.Request)
	// RequestPasswordReset Send a password reset email (always 204, no account enumeration)
	// (POST /api/admin/v1/auth/password-reset/request)
	RequestPasswordReset(w http.ResponseWriter, r *http.Request)
	// RegenerateRecoveryCodes Replace the recovery codes (current TOTP code required)
	// (POST /api/admin/v1/auth/recovery-codes)
	RegenerateRecoveryCodes(w http.ResponseWriter, r *http.Request)
	// ConfirmTotp Confirm TOTP enrolment with a code; returns the recovery codes and rotates the session
	// (POST /api/admin/v1/auth/totp/confirm)
	ConfirmTotp(w http.ResponseWriter, r *http.Request)
	// DisableTotp Disable TOTP (password and current code required)
	// (POST /api/admin/v1/auth/totp/disable)
	DisableTotp(w http.ResponseWriter, r *http.Request)
	// EnrollTotp Start TOTP enrolment (new secret, QR code)
	// (POST /api/admin/v1/auth/totp/enroll)
	EnrollTotp(w http.ResponseWriter, r *http.Request)
	// ListEventTypes Catalogue of event types
	// (GET /api/admin/v1/event-types)
	ListEventTypes(w http.ResponseWriter, r *http.Request)
	// GetMarina A marina (marina.read)
	// (GET /api/admin/v1/marinas/{marinaId})
	GetMarina(w http.ResponseWriter, r *http.Request, marinaId MarinaId)
	// UpdateMarina Update marina settings (marina.configure)
	// (PATCH /api/admin/v1/marinas/{marinaId})
	UpdateMarina(w http.ResponseWriter, r *http.Request, marinaId MarinaId, params UpdateMarinaParams)
	// ListApiKeys API keys of the marina (users.manage)
	// (GET /api/admin/v1/marinas/{marinaId}/api-keys)
	ListApiKeys(w http.ResponseWriter, r *http.Request, marinaId MarinaId)
	// CreateApiKey Create an API key; the secret is returned once (users.manage)
	// (POST /api/admin/v1/marinas/{marinaId}/api-keys)
	CreateApiKey(w http.ResponseWriter, r *http.Request, marinaId MarinaId, params CreateApiKeyParams)
	// RevokeApiKey Revoke an API key (users.manage)
	// (DELETE /api/admin/v1/marinas/{marinaId}/api-keys/{apiKeyId})
	RevokeApiKey(w http.ResponseWriter, r *http.Request, marinaId MarinaId, apiKeyId string)
	// ArchiveMarina Archive a marina (organization.manage)
	// (POST /api/admin/v1/marinas/{marinaId}/archive)
	ArchiveMarina(w http.ResponseWriter, r *http.Request, marinaId MarinaId)
	// ListAuditLog Audit log of the marina, newest first (audit.read)
	// (GET /api/admin/v1/marinas/{marinaId}/audit-log)
	ListAuditLog(w http.ResponseWriter, r *http.Request, marinaId MarinaId, params ListAuditLogParams)
	// ListDevices Paired devices of the marina (devices.manage)
	// (GET /api/admin/v1/marinas/{marinaId}/devices)
	ListDevices(w http.ResponseWriter, r *http.Request, marinaId MarinaId)
	// CreatePairingCode Create a pairing code (devices.pair_self for oneself, devices.manage for another user)
	// (POST /api/admin/v1/marinas/{marinaId}/devices/pairing-codes)
	CreatePairingCode(w http.ResponseWriter, r *http.Request, marinaId MarinaId, params CreatePairingCodeParams)
	// RevokeDevice Revoke a device (devices.manage)
	// (DELETE /api/admin/v1/marinas/{marinaId}/devices/{deviceId})
	RevokeDevice(w http.ResponseWriter, r *http.Request, marinaId MarinaId, deviceId string)
	// ListMembers Members of the marina, organization-wide and marina-level (users.manage)
	// (GET /api/admin/v1/marinas/{marinaId}/members)
	ListMembers(w http.ResponseWriter, r *http.Request, marinaId MarinaId)
	// AddMember Add a member to the marina (users.manage); a new user receives an invitation email
	// (POST /api/admin/v1/marinas/{marinaId}/members)
	AddMember(w http.ResponseWriter, r *http.Request, marinaId MarinaId, params AddMemberParams)
	// RemoveMember Remove the marina-level membership of a user (users.manage)
	// (DELETE /api/admin/v1/marinas/{marinaId}/members/{userId})
	RemoveMember(w http.ResponseWriter, r *http.Request, marinaId MarinaId, userId UserId)
	// UpdateMember Change the marina-level role of a member (users.manage)
	// (PATCH /api/admin/v1/marinas/{marinaId}/members/{userId})
	UpdateMember(w http.ResponseWriter, r *http.Request, marinaId MarinaId, userId UserId)
	// SendMemberPasswordReset Email a password reset link to a member (users.manage)
	// (POST /api/admin/v1/marinas/{marinaId}/members/{userId}/password-reset)
	SendMemberPasswordReset(w http.ResponseWriter, r *http.Request, marinaId MarinaId, userId UserId)
	// ListWebhookEndpoints Webhook endpoints of the marina (users.manage)
	// (GET /api/admin/v1/marinas/{marinaId}/webhook-endpoints)
	ListWebhookEndpoints(w http.ResponseWriter, r *http.Request, marinaId MarinaId)
	// CreateWebhookEndpoint Create a webhook endpoint; the signing secret is returned once (users.manage)
	// (POST /api/admin/v1/marinas/{marinaId}/webhook-endpoints)
	CreateWebhookEndpoint(w http.ResponseWriter, r *http.Request, marinaId MarinaId, params CreateWebhookEndpointParams)
	// DeleteWebhookEndpoint Delete a webhook endpoint (users.manage)
	// (DELETE /api/admin/v1/marinas/{marinaId}/webhook-endpoints/{endpointId})
	DeleteWebhookEndpoint(w http.ResponseWriter, r *http.Request, marinaId MarinaId, endpointId EndpointId)
	// GetWebhookEndpoint A webhook endpoint (users.manage)
	// (GET /api/admin/v1/marinas/{marinaId}/webhook-endpoints/{endpointId})
	GetWebhookEndpoint(w http.ResponseWriter, r *http.Request, marinaId MarinaId, endpointId EndpointId)
	// UpdateWebhookEndpoint Update a webhook endpoint (users.manage)
	// (PATCH /api/admin/v1/marinas/{marinaId}/webhook-endpoints/{endpointId})
	UpdateWebhookEndpoint(w http.ResponseWriter, r *http.Request, marinaId MarinaId, endpointId EndpointId, params UpdateWebhookEndpointParams)
	// ListWebhookDeliveries Deliveries of an endpoint, newest first (users.manage)
	// (GET /api/admin/v1/marinas/{marinaId}/webhook-endpoints/{endpointId}/deliveries)
	ListWebhookDeliveries(w http.ResponseWriter, r *http.Request, marinaId MarinaId, endpointId EndpointId, params ListWebhookDeliveriesParams)
	// RedeliverWebhook Queue a delivery again (users.manage)
	// (POST /api/admin/v1/marinas/{marinaId}/webhook-endpoints/{endpointId}/deliveries/{deliveryId}/redeliver)
	RedeliverWebhook(w http.ResponseWriter, r *http.Request, marinaId MarinaId, endpointId EndpointId, deliveryId string, params RedeliverWebhookParams)
	// RotateWebhookSecret Rotate the signing secret; the previous one stays valid for 24 hours (users.manage)
	// (POST /api/admin/v1/marinas/{marinaId}/webhook-endpoints/{endpointId}/rotate-secret)
	RotateWebhookSecret(w http.ResponseWriter, r *http.Request, marinaId MarinaId, endpointId EndpointId)
	// TestWebhookEndpoint Queue a webhook.test delivery (users.manage)
	// (POST /api/admin/v1/marinas/{marinaId}/webhook-endpoints/{endpointId}/test)
	TestWebhookEndpoint(w http.ResponseWriter, r *http.Request, marinaId MarinaId, endpointId EndpointId, params TestWebhookEndpointParams)
	// GetMeta Version, edition and capabilities of this instance
	// (GET /api/admin/v1/meta)
	GetMeta(w http.ResponseWriter, r *http.Request)
	// ListOrganizations Organizations of the principal
	// (GET /api/admin/v1/organizations)
	ListOrganizations(w http.ResponseWriter, r *http.Request)
	// UpdateOrganization Update the organization (organization.manage)
	// (PATCH /api/admin/v1/organizations/{organizationId})
	UpdateOrganization(w http.ResponseWriter, r *http.Request, organizationId OrganizationId, params UpdateOrganizationParams)
	// ListMarinas Marinas of the organization visible to the principal
	// (GET /api/admin/v1/organizations/{organizationId}/marinas)
	ListMarinas(w http.ResponseWriter, r *http.Request, organizationId OrganizationId)
	// CreateMarina Create a marina (organization.manage)
	// (POST /api/admin/v1/organizations/{organizationId}/marinas)
	CreateMarina(w http.ResponseWriter, r *http.Request, organizationId OrganizationId, params CreateMarinaParams)
	// ListOrgOwners Organization-wide owners (organization.manage)
	// (GET /api/admin/v1/organizations/{organizationId}/owners)
	ListOrgOwners(w http.ResponseWriter, r *http.Request, organizationId OrganizationId)
	// AddOrgOwner Add an organization-wide owner (the role in the body is ignored)
	// (POST /api/admin/v1/organizations/{organizationId}/owners)
	AddOrgOwner(w http.ResponseWriter, r *http.Request, organizationId OrganizationId, params AddOrgOwnerParams)
	// RemoveOrgOwner Remove an organization-wide owner (the last one cannot be removed)
	// (DELETE /api/admin/v1/organizations/{organizationId}/owners/{userId})
	RemoveOrgOwner(w http.ResponseWriter, r *http.Request, organizationId OrganizationId, userId UserId)
	// Stream Server-sent events of a marina (marina.read)
	// (GET /api/admin/v1/stream)
	Stream(w http.ResponseWriter, r *http.Request, params StreamParams)
	// DemoPairDevice Pair as the demo user without a code (demo installations only)
	// (POST /api/device/v1/demo-pairing)
	DemoPairDevice(w http.ResponseWriter, r *http.Request)
	// PairDevice Exchange a pairing code for a device token (shown once)
	// (POST /api/device/v1/pair)
	PairDevice(w http.ResponseWriter, r *http.Request, params PairDeviceParams)
	// UnpairDeviceSelf Revoke the calling device's token
	// (DELETE /api/device/v1/self)
	UnpairDeviceSelf(w http.ResponseWriter, r *http.Request)
	// GetDeviceSelf The calling device, its user, marina and permissions
	// (GET /api/device/v1/self)
	GetDeviceSelf(w http.ResponseWriter, r *http.Request)
	// GetPublicMarina Public information of a marina
	// (GET /api/public/v1/{slug})
	GetPublicMarina(w http.ResponseWriter, r *http.Request, slug string)
	// Healthz Liveness probe
	// (GET /healthz)
	Healthz(w http.ResponseWriter, r *http.Request)
	// Readyz Readiness probe (database reachable, migrations applied)
	// (GET /readyz)
	Readyz(w http.ResponseWriter, r *http.Request)
}

